import re
H = re.compile(r'^(?P<level>error|warning|note|help)(?:\[(?P<code>[A-Z]\d+)\])?: (?P<message>.*)$')
L = re.compile(r'^\s*-->\s*(?P<file>.+?):(?P<line>\d+):(?P<column>\d+)\s*$')
G = re.compile(r'^\s*(?P<num>\d*)\s*\|(?P<rest>.*)$')
N = re.compile(r'^\s*=\s*(?P<level>note|help|warning): ?(?P<message>.*)$')
M = re.compile(r'^\s*(?P<marker>[-^+|~]+)\s*(?P<label>.*)$')

def parse(lines):
    diags, src, labs, notes = [], [], [], []
    dl, sl, ll, nl, kl = [], [], [], [], []
    summ = {}
    skip = []
    did = 0
    last = None
    for i, t in enumerate(lines):
        if not t.strip():
            continue
        m = H.match(t)
        if m:
            msg = m.group('message')
            if m.group('level') == 'error' and msg.startswith('aborting due to'):
                summ['result'] = msg
                kl.append(i)
                continue
            if m.group('level') in ('error', 'warning'):
                did += 1
            last = {'diagnostic': did, 'level': m.group('level'), 'code': m.group('code') or '', 'message': msg, 'file': '', 'line': '', 'column': ''}
            diags.append(last)
            dl.append(i)
            continue
        m = L.match(t)
        if m and last is not None:
            last['file'] = m.group('file')
            last['line'] = int(m.group('line'))
            last['column'] = int(m.group('column'))
            dl.append(i)
            continue
        m = N.match(t)
        if m:
            notes.append({'diagnostic': did, 'level': m.group('level'), 'message': m.group('message')})
            nl.append(i)
            continue
        m = G.match(t)
        if m:
            rest = m.group('rest')
            if m.group('num'):
                code = rest[1:] if rest.startswith(' ') else rest
                src.append({'diagnostic': did, 'line': int(m.group('num')), 'code': code})
                sl.append(i)
            elif rest.strip():
                mm = M.match(rest)
                if mm:
                    labs.append({'diagnostic': did, 'marker': mm.group('marker'), 'label': mm.group('label')})
                else:
                    labs.append({'diagnostic': did, 'marker': '', 'label': rest.strip()})
                ll.append(i)
            else:
                skip.append(i)
            continue
        m = re.match(r'^Some errors have detailed explanations:\s*(.*?)\.?$', t)
        if m:
            summ['explanations'] = m.group(1)
            kl.append(i)
            continue
        if t.startswith('For more information'):
            summ['more_info'] = t.strip()
            kl.append(i)
            continue
    blocks = []
    if diags:
        blocks.append({'name': 'diagnostics', 'kind': 'table', 'lines': dl, 'records': diags})
    if src:
        blocks.append({'name': 'source_lines', 'kind': 'table', 'lines': sl, 'records': src})
    if labs:
        blocks.append({'name': 'labels', 'kind': 'table', 'lines': ll, 'records': labs})
    if notes:
        blocks.append({'name': 'notes', 'kind': 'table', 'lines': nl, 'records': notes})
    if summ:
        blocks.append({'name': 'summary', 'kind': 'kv', 'lines': kl, 'records': [summ]})
    return {'blocks': blocks, 'skip': skip}
